import { Component, computed, signal } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import { TablerIconComponent } from '@tabler/icons-angular';
import * as Tabler from '@tabler/icons-angular';

interface IconItem { name: string; obj: any; }

// Toàn bộ icon Tabler (~5900). Lấy trực tiếp từ package — mỗi icon là object
// { name, type, nodes }. Dùng OBJECT MODE để render an toàn (không cần register).
const ALL_ICONS: IconItem[] = Object.entries(Tabler as Record<string, any>)
  .filter(([k, v]) => k.startsWith('Icon') && v && typeof v === 'object' && 'nodes' in v && 'name' in v)
  .map(([, v]) => ({ name: v.name as string, obj: v }))
  .sort((a, b) => a.name.localeCompare(b.name));

/** Foundation · Icons — browser toàn bộ Tabler (icon standard dự án).
 *
 * 2 cách dùng:
 *  - OBJECT mode (khuyến nghị): `<tabler-icon [icon]="IconTruck" />` — import trực
 *    tiếp, tree-shakeable, KHÔNG cần register, gõ sai = lỗi compile (không crash).
 *  - STRING mode: `<tabler-icon icon="truck" />` — cần register icon ở app.config
 *    provideTablerIcons; chỉ dùng khi tên icon động (data-driven).
 *
 * → Component sau này chọn icon hợp nghĩa từ CẢ bộ Tabler, không giới hạn trang này.
 */
@Component({
  selector: 'sg-icons',
  imports: [TranslateModule, TablerIconComponent],
  template: `
    <h1 class="sg-h">{{ 'sg.nav.icons' | translate }}</h1>
    <p class="sg-desc">{{ 'sg.icons.desc' | translate }}</p>

    <div class="search-bar">
      <tabler-icon [icon]="searchIcon" [size]="18" class="s-ico" />
      <input class="search" [value]="query()" (input)="query.set($any($event.target).value)"
        [placeholder]="'sg.icons.search' | translate" />
      <span class="count">{{ filtered().length }} / {{ total }}</span>
    </div>

    <div class="ico-grid">
      @for (i of shown(); track i.name) {
        <div class="ico-cell" [title]="i.name">
          <tabler-icon [icon]="i.obj" [size]="22" />
          <span class="ico-name">{{ i.name }}</span>
        </div>
      }
    </div>
    @if (filtered().length > shown().length) {
      <div class="more">{{ 'sg.icons.more' | translate:{ n: filtered().length - shown().length } }}</div>
    }
    @if (filtered().length === 0) {
      <div class="more">{{ 'sg.icons.none' | translate }}</div>
    }
  `,
  styleUrls: ['../sg-page.css'],
  styles: [`
    .search-bar {
      position: sticky; top: -32px; z-index: 1;
      display: flex; align-items: center; gap: 10px;
      background: var(--bg-app); padding: 8px 0 16px;
    }
    .s-ico { color: var(--text-sub); }
    .search {
      flex: 1; max-width: 420px; height: 40px; padding: 0 14px;
      border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
      background: var(--bg-surface); color: var(--text-strong);
      font-family: var(--font-sans); font-size: var(--fs-14); outline: none;
    }
    .search:focus { border-color: var(--border-focus); box-shadow: var(--shadow-focus-primary); }
    .count { font-size: var(--fs-12); color: var(--text-sub); font-variant-numeric: tabular-nums; }
    .ico-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(112px, 1fr)); gap: 8px; }
    .ico-cell {
      display: flex; flex-direction: column; align-items: center; gap: 8px;
      padding: 14px 6px; border: 1px solid var(--border-sub); border-radius: var(--radius-lg);
      background: var(--bg-surface); color: var(--text-body); cursor: default;
      transition: border-color var(--duration-fast) var(--ease-out), color var(--duration-fast) var(--ease-out);
    }
    .ico-cell:hover { border-color: var(--primary-base); color: var(--primary-base); }
    .ico-name { font-size: var(--fs-11); color: var(--text-sub); text-align: center; word-break: break-all; line-height: 1.3; }
    .ico-cell:hover .ico-name { color: var(--text-strong); }
    .more { margin-top: 16px; font-size: var(--fs-13); color: var(--text-sub); }
  `],
})
export class SgIcons {
  protected readonly total = ALL_ICONS.length;
  protected readonly searchIcon: any = Tabler.IconSearch;
  protected readonly query = signal('');
  protected readonly cap = 300;

  protected readonly filtered = computed(() => {
    const q = this.query().trim().toLowerCase();
    return q ? ALL_ICONS.filter((i) => i.name.includes(q)) : ALL_ICONS;
  });
  protected readonly shown = computed(() => this.filtered().slice(0, this.cap));
}
